import { Hono } from "hono";
import { z } from "zod";
import { runAgent } from "@jynx/runtime";
import { enforceBudget } from "../middleware/budget";
import { enforceHonesty } from "../middleware/honesty";
const app = new Hono();
const RunRequest = z.object({
  threadId: z.string().optional(),
  goal: z.string().min(1),
  faculty: z.enum(["gse", "coding", "personal"]).default("gse"),
  maxSteps: z.number().int().min(1).max(30).default(12),
});
